import os
import urllib.parse

from features import normalize_url

# Popular domains are treated as Safe before the model runs: a lexical model can't tell
# bbc.co.uk/news/technology from a phishing path, but popularity is strong evidence on its own.
# allowlist.txt is generated by url_model_v4.ipynb from the Tranco top-sites list.
ALLOWLIST_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'allowlist.txt')

# Platforms where anyone can publish content under the platform's (popular) domain - phishing
# kits are routinely hosted on these, so they are never allowlisted however popular they are
PLATFORM_SUFFIXES = (
    # Site builders and blogs
    'blogspot.com', 'wordpress.com', 'wixsite.com', 'weebly.com', 'webflow.io', 'squarespace.com',
    'godaddysites.com', 'square.site', 'jimdosite.com', 'canva.site', 'notion.site', 'carrd.co',
    'mybluehost.me', '000webhostapp.com', 'tilda.ws', 'strikingly.com', 'ucoz.com', 'telegra.ph',
    'freewebs.com', 'webs.com', 'angelfire.com', 'tripod.com', 'yolasite.com', 'wix.com',
    # Static and serverless hosting
    'github.io', 'gitlab.io', 'pages.dev', 'workers.dev', 'r2.dev', 'vercel.app', 'netlify.app',
    'herokuapp.com', 'firebaseapp.com', 'web.app', 'appspot.com', 'azurewebsites.net',
    'windows.net', 'cloudfront.net', 'amazonaws.com', 'glitch.me', 'repl.co', 'replit.app',
    'onrender.com', 'fly.dev', 'surge.sh', 'ipfs.io', 'dweb.link', 'ngrok.io', 'ngrok-free.app',
    'trycloudflare.com', 'duckdns.org', 'googleusercontent.com', 'wpenginepowered.com',
    'b-cdn.net', 'storage.cloud.google.com', 'script.google.com',
    # Wildcard and dynamic DNS - anyone can mint any hostname under these
    'nip.io', 'sslip.io', 'xip.io', 'localtest.me', 'lvh.me', 'ddns.net', 'hopto.org', 'zapto.org',
    'no-ip.com', 'no-ip.org', 'dynu.com', 'freedns.afraid.org', 'serveo.net', 'loca.lt',
    # Marketing tools whose hosted forms and pages are a common phishing vehicle
    'hsforms.com', 'hubspotpagebuilder.com', 'campaign-archive.com', 'list-manage.com',
    # User content on big platforms
    'sites.google.com', 'docs.google.com', 'drive.google.com', 'forms.gle', 'storage.googleapis.com',
    'firebasestorage.googleapis.com', 'dropboxusercontent.com', 'dl.dropbox.com', 'onedrive.live.com',
    '1drv.ms', 'sharepoint.com', 'box.com', 'mediafire.com', 'typeform.com', 'jotform.com',
    'formstack.com', 'linktr.ee', 'discord.gg', 't.me',
    # URL shorteners
    'bit.ly', 'tinyurl.com', 't.co', 'is.gd', 'goo.gl', 'ow.ly', 'buff.ly', 'rebrand.ly',
    'cutt.ly', 'shorturl.at', 'qrco.de', 'rb.gy',
)


# Document platforms people open every day. Their URLs are opaque IDs (docs.google.com/forms/d/<id>),
# so a phishing form and a real one are lexically identical and the model can only guess. These are
# never blocked: a wrong block here breaks everyday work, while phishing hosted on them is left to
# the platforms' own abuse detection. Checked separately from the allowlist, which still excludes them.
NEVER_BLOCK_SUFFIXES = (
    'docs.google.com', 'drive.google.com', 'forms.gle',
    'sharepoint.com', 'onedrive.live.com', 'onedrive.com', '1drv.ms',
)


def _load_allowlist():
    if not os.path.exists(ALLOWLIST_PATH):
        return frozenset()
    with open(ALLOWLIST_PATH, encoding='utf-8') as f:
        return frozenset(line.strip() for line in f if line.strip() and not line.startswith('#'))


ALLOWLIST = _load_allowlist()


def _matches_suffix(hostname, suffix):
    return hostname == suffix or hostname.endswith('.' + suffix)


def is_platform(hostname):
    return any(_matches_suffix(hostname, s) for s in PLATFORM_SUFFIXES)


def _hostname(url):
    try:
        return urllib.parse.urlparse('http://' + normalize_url(url)).hostname or ''
    except ValueError:
        return ''


def is_never_block(url):
    """True if the URL is on a document platform the shield never blocks."""
    hostname = _hostname(url)
    return bool(hostname) and any(_matches_suffix(hostname, s) for s in NEVER_BLOCK_SUFFIXES)


def is_allowlisted(url, allowlist=None):
    """True if the URL's host, or a parent domain of it, is in the allowlist."""
    allowlist = ALLOWLIST if allowlist is None else allowlist
    hostname = _hostname(url)
    if not hostname or is_platform(hostname):
        return False

    # news.bbc.co.uk -> news.bbc.co.uk, bbc.co.uk (never a bare TLD)
    labels = hostname.split('.')
    return any('.'.join(labels[i:]) in allowlist for i in range(len(labels) - 1))
